                        "type": "string"
                    },
                    "geoLocationPoint": {
                        "additionalProperties": false,
                        "description": "A point location in space.",
                        "properties": {
                            "pointLatitude": {
                                "description": "Latitudinal dimension of point.",
                                "type": "number"
