                            "polygonPoints": {
                                "description": "A point location in a polygon.",
                                "items": {
                                    "additionalProperties": false,
                                    "properties": {
                                        "pointLatitude": {
                                            "description": "Latitudinal dimension of point.",
                                            "type": "number"
                                        },
                                        "pointLongitude": {
                                            "description": "Longitudinal dimension of point.",
                                            "type": "number"
                                        }
                                    },
                                    "required": [
                                        "pointLongitude",
                                        "pointLatitude"
                                    ],
                                    "type": "object"
                                },
