                                "type": "array"
                            }
                        },
                        "required": [
                            "polygonPoints"
                        ],
                        "type": "object"
                    }
                },
                "type": "object"
            },
            "type": "array"
        },
        "identifier": {
            "additionalProperties": false,
            "description": "A persistent identifier that identifies a resource. Currently, only DOI is allowed.",
